examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    formError?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
    when (step) {
        "request" -> {
            MonarchText(text = "Reset your password", style = MonarchTextStyle.Title, modifier = Modifier.semantics { heading() })
            MonarchText(text = "Enter the email address of your account and we’ll send you a link to choose a new password.")
            MonarchTextField(
                value = email,
                onValueChange = { email = it },
                label = "Email",
                required = true,
                errorText = emailError,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email, autoCorrectEnabled = false),
            )
            MonarchButton(
                text = "Send reset link",
                onClick = {
                    if ("@" !in email || "." !in email) {
                        emailError = "Enter an email address like name@example.com."
                    } else {
                        emailError = null
                        working = true
                        scope.launch {
                            // The app's request. Put a failure in formError.
                            working = false
                            step = "sent"
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                loading = working,
            )
            MonarchButton(
                text = "Back to sign in",
                onClick = {},
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Link,
            )
        }
        "sent" -> {
            MonarchText(text = "Check your email", style = MonarchTextStyle.Title, modifier = Modifier.semantics { heading() })
            MonarchText(text = "If an account exists for $email, you’ll get an email with a link to reset your password.")
            MonarchButton(text = "Use a different email", onClick = { step = "request" }, variant = MonarchButtonVariant.Ghost)
        }
        "reset" -> {
            MonarchText(text = "Choose a new password", style = MonarchTextStyle.Title, modifier = Modifier.semantics { heading() })
            MonarchPasswordInput(
                value = password,
                onValueChange = { password = it },
                label = "New password",
                purpose = MonarchPasswordInputPurpose.New,
            )
            MonarchPasswordStrengthMeter(password = password, rules = rules)
            MonarchPasswordInput(
                value = confirmation,
                onValueChange = { confirmation = it },
                label = "Confirm new password",
                errorText = mismatch,
                purpose = MonarchPasswordInputPurpose.New,
            )
            MonarchButton(
                text = "Change password",
                onClick = {
                    working = true
                    scope.launch {
                        // The app saves the password with resetToken. An expired link goes in formError.
                        working = false
                        step = "done"
                    }
                },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
                enabled = meetsRules && confirmation.isNotEmpty() && mismatch == null,
                loading = working,
            )
        }
        else -> {
            MonarchText(text = "Password changed", style = MonarchTextStyle.Title, modifier = Modifier.semantics { heading() })
            MonarchText(text = "You can now sign in with your new password.")
            MonarchButton(
                text = "Back to sign in",
                onClick = { step = "request" },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
            )
        }
    }
}

examples.setupTemplate:
val scope = rememberCoroutineScope()
// The token from the App Link that opened the app, or null. The activity reads it from intent.data.
val resetToken: String? = null
var step by rememberSaveable { mutableStateOf(if (resetToken != null) "reset" else "request") }
var email by rememberSaveable { mutableStateOf({{email}}) }
var emailError by remember { mutableStateOf<String?>(null) }
var password by remember { mutableStateOf("") }
var confirmation by remember { mutableStateOf("") }
var working by remember { mutableStateOf(false) }
var formError by remember { mutableStateOf<String?>(null) }
val rules = MonarchPasswordRule.defaults()
val meetsRules = rules.all { it.test(password) }
val mismatch = if (confirmation.isEmpty() || confirmation == password) null else "The passwords don’t match."

